// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address newKeeper) public {
        // The owner-gated path only exists after initialization. initialize needs a
        // glpManager whose vault() returns an address; deploy an adversarial-style
        // helper callee for that external call and route c's external interaction
        // through it.
        GlpManagerStub mgr = new GlpManagerStub();

        // Drive c.initialize through its public surface (typed interface params are
        // opaque to the test file, so use the ABI-encoded public call).
        (bool okInit, ) = address(c).call(
            abi.encodeWithSelector(
                bytes4(keccak256("initialize(address,address,address,address,address,address)")),
                address(mgr),
                address(mgr),
                address(mgr),
                address(mgr),
                address(this),
                address(this)
            )
        );
        assertTrue(okInit, "initialize must succeed");

        // General rule: the initializing account is owner, so setKeeper(newKeeper)
        // succeeds for ANY fuzzed keeper address and keeper() reflects it.
        vm.prank(address(this));
        bool ok;
        try c.setKeeper(newKeeper) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.keeper() == newKeeper, "owner-gated setKeeper must succeed and set keeper");
    }
}

// Minimal external callee required by initialize; without deployed code the
// staticcall to vault() would fail. Routed through by c during initialization.
contract GlpManagerStub {
    address public vault = address(0x1234);
}
